import{_ as a,o,c as r,a2 as t}from"./chunks/framework.DTwTvi8b.js";const u=JSON.parse('{"title":"0019 用 Paseo 的并行子 agent：确认前独立审阅、方案提案","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0019-parallel-orchestration.md","filePath":"reference/adr/0019-parallel-orchestration.md","lastUpdated":null}'),s={name:"reference/adr/0019-parallel-orchestration.md"};function i(l,e,d,c,n,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<div><h1 id="_0019-用-paseo-的并行子-agent-确认前独立审阅、方案提案" tabindex="-1">0019 用 Paseo 的并行子 agent：确认前独立审阅、方案提案 <a class="header-anchor" href="#_0019-用-paseo-的并行子-agent-确认前独立审阅、方案提案" aria-label="Permalink to &quot;0019 用 Paseo 的并行子 agent：确认前独立审阅、方案提案&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>Paseo 自带 <code>/paseo-advisor</code>（第二意见）、<code>/paseo-committee</code>（两个模型独立分析）等编排 skill。它们由聊天 agent 自由发挥，结果没有固定的去处，也不会稳定地写回需求文件；直接让 <code>/req</code> 调用它们还违反&quot;入口不调用入口&quot;（ADR 0008）。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><p>同样的思路由 req-kit 的引擎以固定的步骤实现，产物写进功能目录：</p><ul><li><strong>需求说明审阅</strong>（<code>--spec-review</code>）：在需求方确认之前，由 reviewer（通常与对话用的不是同一个模型）在后台独立审阅草稿，写 <code>spec-review.md</code>，把问题写成带推荐的选择题；完成后通知对话，由对话 agent 核对后逐个问用户。不改 spec、不提交。默认只用于标准档（<code>specReview</code>）。</li><li><strong>方案提案</strong>（<code>designProposals</code>，默认关闭）：标准档的方案设计之前，几个 agent（默认 builder 和 reviewer）并行各提一份方案，方案设计步骤比较后决定，并在 <code>design.md</code> 中写&quot;方案比较&quot;。增量继续时不做。</li><li><strong>浏览器验证</strong>（<code>browserVerify</code>）：步骤 agent 有 Paseo 浏览器工具时，验证类步骤按验收标准在浏览器中实际操作。</li></ul><p>Paseo 的编排 skill 仍然推荐使用者单独使用（例如对一个疑难问题请 <code>/paseo-committee</code>），文档中说明。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>确认前多一次几分钟的审阅，能在开发之前发现遗漏和歧义；方案提案以多一份方案的用量换取复杂需求的方案质量，所以默认关闭。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0019-parallel-orchestration.md">docs/adr/0019-parallel-orchestration.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0019-parallel-orchestration.md">在 GitHub 上编辑</a></p>',2)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
